import Foundation

final class SimpleImageCache {
    private let cache = NSCache<NSString, NSData>()

    func store(data: Data, for key: String) {
        cache.setObject(data as NSData, forKey: key as NSString)
    }

    func retrieve(key: String) -> Data? {
        return cache.object(forKey: key as NSString) as Data?
    }
}

let imageCache = SimpleImageCache()
let raw = "Pixels".data(using: .utf8)!
imageCache.store(data: raw, for: "avatar")
let fetched = imageCache.retrieve(key: "avatar")
print("Found: \(fetched != nil)")

