import Foundation

func isResponseFresh(cached: CachedURLResponse) -> Bool {
    guard let http = cached.response as? HTTPURLResponse,
          let control = http.value(forHTTPHeaderField: "Cache-Control") else {
        return true
    }
    return !control.contains("no-store")
}

let url = URL(string: "https://example.com")!
let headers = ["Cache-Control": "max-age=3600"]
let resp = HTTPURLResponse(url: url, statusCode: 200, httpVersion: nil, headerFields: headers)!
let cached = CachedURLResponse(response: resp, data: Data())
let fresh = isResponseFresh(cached: cached)
print("Fresh: \(fresh)")
